function graficoBarras(datos, { ancho = 400, alto = 200, margen = 24 } = {}) {
  const max = Math.max(1, ...datos.map(d => d.valor));
  const paso = (ancho - margen * 2) / datos.length;
  const barras = datos.map((d, i) => {
    const h = (d.valor / max) * (alto - margen * 2);
    const x = margen + i * paso + paso * 0.15;
    const y = alto - margen - h;
    return `<rect x="${x}" y="${y}" width="${paso * 0.7}" height="${h}" rx="3" fill="var(--color-principal)"/>
      <text x="${x + paso * 0.35}" y="${alto - 6}" text-anchor="middle" font-size="11">${esc(d.etiqueta)}</text>
      <text x="${x + paso * 0.35}" y="${y - 4}" text-anchor="middle" font-size="11">${d.valor}</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${ancho} ${alto}" role="img" aria-label="Gráfico de barras">${barras}</svg>`;
}

function puntosLinea(valores, ancho, alto) {
  const max = Math.max(1, ...valores);
  const paso = ancho / Math.max(1, valores.length - 1);
  return valores.map((v, i) => `${i * paso},${alto - (v / max) * alto}`).join(' ');
}
// <polyline points="${puntosLinea(serie, 400, 160)}" fill="none" stroke="var(--color-principal)" stroke-width="2"/>

function dona(partes, r = 60) {
  const C = 2 * Math.PI * r, total = partes.reduce((s, p) => s + p.valor, 0) || 1;
  let acumulado = 0;
  const arcos = partes.map(p => {
    const largo = (p.valor / total) * C;
    const arco = `<circle r="${r}" cx="80" cy="80" fill="none" stroke="${p.color}" stroke-width="22"
      stroke-dasharray="${largo} ${C}" stroke-dashoffset="${-acumulado}" transform="rotate(-90 80 80)"/>`;
    acumulado += largo;
    return arco;
  }).join('');
  return `<svg viewBox="0 0 160 160" role="img" aria-label="Distribución">${arcos}</svg>`;
}

